INSERT INTO announcements (id, title, content, target_audience, target_class_id, target_role, author_id, published_at, expires_at, is_published)
VALUES
  ('an00001-0000-0000-0000-000000000001', 'Selamat Datang di Tahun Ajaran 2024/2025', 'Selamat datang kepada seluruh siswa baru dan lama. Semoga tahun ajaran ini membawa keberhasilan bagi kita semua. Jadwal pelajaran sudah dapat diakses melalui sistem.', 'all', NULL, NULL, 'p0000003-0000-0000-0000-000000000003', '2024-07-08', '2024-08-31', TRUE),
  ('an00002-0000-0000-0000-000000000002', 'Jadwal Ujian Tengah Semester', 'Ujian Tengah Semester (UTS) akan dilaksanakan pada tanggal 16-27 September 2024. Seluruh siswa diharapkan mempersiapkan diri dengan baik. Jadwal lengkap akan diumumkan masing-masing wali kelas.', 'all', NULL, 'siswa', 'p0000004-0000-0000-0000-000000000004', '2024-09-01', '2024-09-30', TRUE),
  ('an00003-0000-0000-0000-000000000003', 'Pengumuman Libur Nasional', 'Berdasarkan keputusan pemerintah, hari Jumat tanggal 18 Oktober 2024 dinyatakan sebagai hari libur nasional. Kegiatan belajar mengajar akan dilanjutkan pada hari Senin tanggal 21 Oktober 2024.', 'all', NULL, NULL, 'p0000002-0000-0000-0000-000000000002', '2024-10-10', NULL, TRUE);
INSERT INTO notifications (id, user_id, title, message, type, reference_type, reference_id, is_read, created_at)
VALUES
  ('nt00001-0000-0000-0000-000000000001', 'p0000005-0000-0000-0000-000000000005', 'Jadwal Mengajar Diperbarui', 'Jadwal mengajar kelas X-A untuk semester ganjil sudah diperbarui. Silakan cek jadwal terbaru.', 'info', 'schedule', NULL, FALSE, '2024-07-08 08:00:00+07'),
  ('nt00002-0000-0000-0000-000000000002', 'p0000011-0000-0000-0000-000000000011', 'Pengumuman Kelas Baru', 'Selamat! Anda telah terdaftar di kelas X-A tahun ajaran 2024/2025. Silakan cek jadwal pelajaran.', 'success', 'class_student', NULL, FALSE, '2024-07-08 09:00:00+07'),
  ('nt00003-0000-0000-0000-000000000003', 'p0000006-0000-0000-0000-000000000006', 'Input Nilai Tenggat', 'Harap input nilai UH Matematika kelas X-B sebelum tanggal 30 Juli 2024.', 'warning', 'grade', NULL, FALSE, '2024-07-20 10:00:00+07'),
  ('nt00004-0000-0000-0000-000000000004', 'p0000002-0000-0000-0000-000000000002', 'Laporan Absensi', 'Laporan absensi minggu ini sudah tersedia. 5 siswa X-A tidak hadir tanpa keterangan.', 'info', 'attendance', NULL, FALSE, '2024-07-19 16:00:00+07'),
  ('nt00005-0000-0000-0000-000000000005', 'p0000004-0000-0000-0000-000000000004', 'Persiapan UTS', 'Persiapan Ujian Tengah Semester sudah dimulai. Pastikan semua guru sudah menginput nilai remedial.', 'warning', NULL, NULL, FALSE, '2024-09-01 07:00:00+07');
